import{_ as u,a0 as l,w as o,s as a,I as n,x as p,a1 as r,A as s,ao as d}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const f=JSON.parse('{"title":"一步步安装Ubuntu 13.10服务版 | LCTT x X-CMD","titleTemplate":false,"description":"一步步安装Ubuntu 13.10服务版 | LCTT (201311) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"一步步安装Ubuntu 13.10服务版 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"一步步安装Ubuntu 13.10服务版 | LCTT (201311) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201311/Install Ubuntu 13.10 Server Step by Step","title":"一步步安装Ubuntu 13.10服务版","tag":"201311","desc":""},"relativePath":"201311/Install Ubuntu 13.10 Server Step by Step.md","filePath":"[post].md"}'),i={name:"201311/Install Ubuntu 13.10 Server Step by Step.md"};function g(m,t,c,S,b,v){const e=l("Link");return o(),a("div",null,[t[14]||(t[14]=n("h1",{id:"一步步安装ubuntu-13-10服务版",tabindex:"-1"},[p("一步步安装Ubuntu 13.10服务版 "),n("a",{class:"header-anchor",href:"#一步步安装ubuntu-13-10服务版","aria-label":"Permalink to “一步步安装Ubuntu 13.10服务版”"},"​")],-1)),t[15]||(t[15]=n("p",null,[p("如你所见，这是一篇关于"),n("strong",null,"Ubuntu 13.10服务版的安装"),p("的指南。")],-1)),n("p",null,[t[1]||(t[1]=p("下载最新的版本",-1)),n("strong",null,[r(e,{href:"http://releases.ubuntu.com/saucy/"},{default:s(()=>[...t[0]||(t[0]=[p("Ubuntu 13.10 服务版",-1)])]),_:1})]),t[2]||(t[2]=p("，然后用刻录好的Ubuntu 13.10服务版光盘引导你的服务器，你将会看到类似下面的显示。",-1))]),t[16]||(t[16]=d('<p>首先选择您的语言：（建议使用英文）</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2013/10/Server1.png" alt=""></p><p>点击安装Ubuntu服务版：</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2013/10/Server2.png" alt=""></p><p>选择安装过程中所使用的语言：</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2013/10/Server3.png" alt=""></p><p>选择你的国家（译注：用于决定时区，请选择中国，使用+8时区）：</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2013/10/Server4.png" alt=""></p><p>配置区域设置：（译注：对于服务器版本，我们建议一律采用英文的locale—— en_US.UTF-8，当然，你可以增加中文字体包，但是保持服务器环境是英文环境，有助于减少出现奇怪问题的几率。）</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2013/10/Server5.png" alt=""></p><p>检测键盘布局（译注：一般不必检测）：</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2013/10/Server6.png" alt=""></p><p>选择键盘布局（译注：如下图的英文即可）：</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2013/10/Server7.png" alt=""></p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2013/10/Server8.png" alt=""></p><p>自动检测网络设置：</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2013/10/Server9.png" alt=""></p><p>输入你的服务器主机名（译注：作为服务器，尤其是运行在互联网上的，一般都输入包括域名在内的完全限定主机名。）：</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2013/10/Server10.png" alt=""></p><p>输入用户名以创建一个非特权用户（译注：操作服务器要习惯使用普通用户操作，<strong>仅仅</strong>在必要使用使用sudo来使用root权限。）：</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2013/10/Server11.png" alt=""></p><p>设置用户的密码：</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2013/10/Server12.png" alt=""></p><p>如果你想加密用户主目录，选择Yes，否则选择No（译注：这点无所谓。）：</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2013/10/Server13.png" alt=""></p><p>选择分区方案（译注：如果你有特定需求，可以采用manual分区方式，没有经验的用户可以使用预设的Guied分区模式。关于分区，是一个值得系统管理员仔细研究的课题，建议搜索更多深入的文章来看看，或者在此进行讨论）：</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2013/10/Server14.png" alt=""></p><p>开始安装：</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2013/10/Server15.png" alt=""></p><p>如果在你的网络上有代理服务，输入代理服务的IP地址（译注：绝大多数的服务器都是直接接入互联网，并有公网IP的，所以不会使用代理服务器的。）：</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2013/10/Server16.png" alt=""></p><p>选择安全更新的安装方式，然后回车（译注：我不同意原文的选择。对于服务器，不建议采用自动更新，因为服务器的第一要务是稳定；在出现必要的安全更新补丁时，系统管理员要评估并测试是否应该安装，是否会对现有应用造成影响，如果可以通过其他方式，如防火墙来消除安全隐患，那么一动不如一静，不安装任何补丁和更新为好。）：</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2013/10/Server17.png" alt=""></p><p>选择要安装的软件（译注：仅仅选择你的服务器所必须的，暂时不用的，最好不要选择。将来需要增加或许修改时，你还有足够的时间去改变。）：</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2013/10/Server18.png" alt=""></p><p>点击Yes安装Grub引导装载程序（译注：这里一般没有别的选择，肯定是安装Grub，除非你有特别的理由给服务器安装其他的引导器。）：</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2013/10/Server20.png" alt=""></p><p>安装完成以后，选择continue重启服务器即可：</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2013/10/Server21.png" alt=""></p><p>登入Ubuntu服务器：</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2013/10/Server22.png" alt=""></p><p>输入用户名和密码登录（译注：如你所见，服务器版默认是没有图形界面的，一般而言，除非你有一个必须图形界面运行的程序，否则不要安装图形界面。不安装图形界面的主要原因是，减少不必要的包和服务，每多一个服务就会多带来一份安全威胁的可能性，当然，也会消耗一点内存和处理能力。你现在可以在登录后输入ps或者pstree看看已经运行的服务有多少。）：</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2013/10/Server23.png" alt=""></p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2013/10/Server24.png" alt=""></p><p>这就是这次的指南。现在你的Ubuntu 13.10 服务版已经启动运行了。</p><hr>',46)),n("p",null,[t[4]||(t[4]=p("via: ",-1)),r(e,{href:"http://www.unixmen.com/install-ubuntu-server-13-10-step-step/"},{default:s(()=>[...t[3]||(t[3]=[p("http://www.unixmen.com/install-ubuntu-server-13-10-step-step/",-1)])]),_:1})]),n("p",null,[t[7]||(t[7]=p("译者：",-1)),r(e,{href:"https://github.com/Luoxcat"},{default:s(()=>[...t[5]||(t[5]=[p("Luoxcat",-1)])]),_:1}),t[8]||(t[8]=p(" 校对：",-1)),r(e,{href:"https://github.com/wxy"},{default:s(()=>[...t[6]||(t[6]=[p("wxy",-1)])]),_:1})]),n("p",null,[t[11]||(t[11]=p("本文由 ",-1)),r(e,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...t[9]||(t[9]=[p("LCTT",-1)])]),_:1}),t[12]||(t[12]=p(" 原创翻译，",-1)),r(e,{href:"http://linux.cn/"},{default:s(()=>[...t[10]||(t[10]=[p("Linux中国",-1)])]),_:1}),t[13]||(t[13]=p(" 荣誉推出",-1))])])}const U=u(i,[["render",g]]);export{f as __pageData,U as default};
